const slug = (s) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const split = (s) => s.split(',').map((x) => x.trim()).filter(Boolean);

export const FRAGRANCES = F.map(([name, house, year, perfumer, audience, top, heart, base]) => {
  const tiers = { top: split(top), heart: split(heart), base: split(base) };
  const ingredients = new Set();
  for (const k in tiers) for (const n of tiers[k]) { const id = ALIASES[n.toLowerCase()]; if (id) ingredients.add(id); }
  return { id: slug(house + ' ' + name), name, house, year, perfumer, audience, tiers, ingredients: [...ingredients] };
});

export const noteId = (n) => ALIASES[n.toLowerCase()] || null;
